// Bubble sort algorithm
// Compare adjacent elements in the array and swap them if they are in the wrong order
// Repeat until no more swaps are needed

function bubbleSort(numbers: number[]): number[] {
  const length = numbers.length;

  // Loop through the array
  for (let I = 0; I < length; i++) {

    // Flag to check if any swaps have been made in this iteration
    let swapped = false;

    // Loop through the array starting at the beginning
    for (let j = 0; j < length - 1 - i; j++) {

      // If the current element is greater than the next...
      if (numbers[j] > numbers[j + 1]) {

        // Swap them
        [numbers[j], numbers[j + 1]] = [numbers[j + 1], numbers[j]];

        // Set the swapped flag to true
        swapped = true;
      }
    }

    // If no swaps were made in this iteration, the array is already sorted
    if (!swapped) {
      break;
    }
  }

  // Return the sorted array
  return numbers;
}

// Main function to test the bubble sort with a given array of numbers
function main(numbers: number[]): void {
  // Check if input is valid
  if (!Array.isArray(numbers) || !numbers.every((n) => typeof n === 'number')) {
    console.error('Error: Invalid input');
    return;
  }

  // Sort the array using bubble sort
  const sortedArray = bubbleSort(numbers);

  // Print the sorted array to the console
  console.log(sortedArray);
}

// Test the script
main([5, 3, 1, 4, 2]); // expected output: [1, 2, 3, 4, 5]
